import kotlinx.coroutines.sync.Semaphore
import kotlinx.coroutines.sync.withPermit

class Bulkhead(private val name: String, maxConcurrent: Int) {
    private val permits = Semaphore(maxConcurrent)

    // fail fast, like Duration.ZERO in the Java version
    suspend fun <T> tryCall(work: suspend () -> T): T {
        if (!permits.tryAcquire()) throw BulkheadFullException("bulkhead '$name' is full")
        try {
            return work()
        } finally {
            permits.release()
        }
    }

    // wait for a permit: the coroutine suspends and holds no thread while it waits
    suspend fun <T> call(work: suspend () -> T): T = permits.withPermit { work() }
}
